-- Official regional population series from Tyumenstat: 22 municipalities, 2022–2025.
-- The source table distinguishes 13 urban districts and 9 municipal districts.
-- Population is stored as persons at January 1; settlement-level rows remain separate.
INSERT INTO public.data_sources
  (id, name, category, url, description, format, coverage, update_frequency, import_status, notes, last_checked_at)
VALUES
  ('rosstat_hmao_municipal_population_2022_2025',
   'Тюменьстат — численность населения городских округов и муниципальных районов Югры на 01.01.2022–2025',
   'demography',
   'https://72.rosstat.gov.ru/ofs_demp_hmao',
   'Официальный XLSX со значениями общей численности населения муниципальных образований ХМАО — Югры на начало 2022, 2023, 2024 и 2025 годов; источник отдельно показывает городское и сельское население.',
   'XLSX',
   '22 муниципальных образования: 13 городских округов и 9 муниципальных районов; 4 среза на 1 января, 2022–2025',
   'Годовая',
   'imported',
   'Импортировано 88 официальных наблюдений общего населения в людях. Принадлежность к городскому округу или муниципальному району сверена с группировкой в исходном файле. Население отдельных населённых пунктов хранится отдельно и не подменяет данные района.',
   now())
ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, category=EXCLUDED.category, url=EXCLUDED.url,
  description=EXCLUDED.description, format=EXCLUDED.format, coverage=EXCLUDED.coverage,
  update_frequency=EXCLUDED.update_frequency, import_status=EXCLUDED.import_status,
  notes=EXCLUDED.notes, last_checked_at=now(), updated_at=now();

