UPDATE public.municipality_indicators AS existing
SET indicator_name = 'Численность постоянного населения муниципального образования на 1 января',
    reference_period = population_input.reference_year::text || '-01-01',
    value = population_input.population,
    unit = 'человек',
    source_id = 'rosstat_hmao_municipal_population_2022_2025',
    source_url = 'https://72.rosstat.gov.ru/storage/mediabank/%D0%A7%D0%B8%D1%81%D0%BB%D0%B5%D0%BD%D0%BE%D1%81%D1%82%D1%8C%20%D0%BD%D0%B0%D1%81%D0%B5%D0%BB%D0%B5%D0%BD%D0%B8%D1%8F%20%D0%A5%D0%9C%D0%90%D0%9E%20%D0%BD%D0%B0%20%D0%BD%D0%B0%D1%87%D0%B0%D0%BB%D0%BE%202022-2025%20%D0%B3%D0%BE%D0%B4%D0%BE%D0%B2.xlsx',
    source_published_at = DATE '2025-04-28',
    verification_status = 'verified',
    notes = 'Тюменьстат, официальный XLSX по городским округам и муниципальным районам Югры; численность на 1 января '
      || population_input.reference_year::text || '. Тип территории: ' || population_input.entity_type
      || '. В источнике отдельно приведены городское и сельское население; импортирован общий итог. Единица: человек.',
    geographic_level = 'municipality',
    geographic_name = population_input.municipality_name,
    retrieved_at = now(),
    updated_at = now()
FROM population_input
WHERE existing.municipality_id = population_input.municipality_id
  AND existing.indicator_code = 'population_municipality'
  AND existing.reference_year = population_input.reference_year
  AND existing.source_id IN ('rosstat_city_population_2024', 'megion_admin_territorial_population');

